const fs = require('fs');
const path = require('path');

const htmlPath = process.argv[2];
const html = fs.readFileSync(htmlPath, 'utf-8');

// Check for external references
const externalRefCheck = !html.match(/https?:\/\//) && !html.match(/<link[^>]*href="https?/) && !html.match(/<script[^>]*src="https?/);
console.log(`✓ No external references: ${externalRefCheck}`);

// Check for inline SVG
const hasSvg = html.includes('<svg');
console.log(`✓ Has inline SVG: ${hasSvg}`);

// Check for inline script/data
const hasScript = html.includes('<script');
console.log(`✓ Has inline script: ${hasScript}`);

// Check for LT-FEATURE-001 progress in JSON data
const progressMatch = html.match(/"progress":\{"done":\s*(\d+),\s*"total":\s*(\d+)\}/);
if (progressMatch) {
  console.log(`✓ Feature progress found: ${progressMatch[1]}/${progressMatch[2]}`);
}

// Check for task nodes
const taskNodes = (html.match(/"kind":\s*"task"/g) || []).length;
console.log(`✓ Task nodes in graph data: ${taskNodes}`);

console.log('\nHTML structure verified ✓');
EOF
