const puppeteer = require('puppeteer');
const fs = require('fs');
const path = require('path');

(async () => {
  const htmlPath = '/private/tmp/claude-501/pr86-ci-live/lt/runs/render86/fx/.dev-graph/render/index.html';
  const html = fs.readFileSync(htmlPath, 'utf-8');

  // Use headless chrome
  const browser = await puppeteer.launch({
    executablePath: '/private/tmp/claude-501/pr86-ci-live/lt/runs/render86/browser/chrome-headless-shell-mac-arm64/chrome-headless-shell',
    headless: 'new',
    args: ['--single-process', '--no-sandbox'],
    timeout: 30000
  });

  const page = await browser.newPage();
  await page.setContent(html, { waitUntil: 'networkidle0' });

  // Check if SVG renders
  const svgCount = await page.$$eval('svg', els => els.length);
  console.log(`✓ SVG elements rendered: ${svgCount}`);

  // Check for feature progress display
  const progressText = await page.evaluate(() => {
    return document.body.innerText;
  });

  if (progressText.includes('LT-FEATURE-001')) {
    console.log('✓ Feature LT-FEATURE-001 visible in rendered page');
  }

  // Check for task elements  
  const taskElements = await page.$$eval('[data-kind="task"]', els => els.length);
  console.log(`✓ Task elements in DOM: ${taskElements}`);

  console.log('\n✓ Browser display verified');
  await browser.close();
})().catch(err => {
  console.error('Browser check failed:', err.message);
  process.exit(1);
});
EOF

